SELECT 
FROM notification n
LEFT JOIN sys_user actor ON actor.id = n.actor_user_id
WHERE n.id = #{notificationId}
  AND n.recipient_user_id = #{recipientUserId}
LIMIT 1

mapper.update:
UPDATE notification
SET is_read = 1,
    read_at = NOW()
WHERE id = #{notificationId}
  AND recipient_user_id = #{recipientUserId}
  AND is_read = 0

mapper.select:
